import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_transpose_conv_ext = None


def _get_transpose_conv_ext():
    global _transpose_conv_ext
    if _transpose_conv_ext is not None:
        return _transpose_conv_ext

    cpp_source = r"""
#include <torch/extension.h>

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv_transpose2d_cuda, "Grouped 2D transposed convolution forward (CUDA)");
}
"""

    cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void transposed_conv2d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t n,
    int64_t in_channels,
    int64_t in_height,
    int64_t in_width,
    int64_t out_channels,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_height,
    int64_t kernel_width,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups,
    int64_t has_bias) {
    const int64_t linear_idx =
        static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;

    const int64_t total = n * out_channels * out_height * out_width;
    if (linear_idx >= total) {
        return;
    }

    int64_t tmp = linear_idx;
    const int64_t ox = tmp % out_width;
    tmp /= out_width;
    const int64_t oy = tmp % out_height;
    tmp /= out_height;
    const int64_t oc = tmp % out_channels;
    const int64_t batch = tmp / out_channels;

    const int64_t out_channels_per_group = out_channels / groups;
    const int64_t in_channels_per_group = in_channels / groups;
    const int64_t group = oc / out_channels_per_group;
    const int64_t oc_in_group = oc - group * out_channels_per_group;

    scalar_t acc = has_bias ? bias[oc] : scalar_t(0);

    for (int64_t ky = 0; ky < kernel_height; ++ky) {
        const int64_t y_num =
            oy + padding_h - ky * dilation_h;

        if (y_num < 0 || y_num % stride_h != 0) {
            continue;
        }

        const int64_t iy = y_num / stride_h;
        if (iy < 0 || iy >= in_height) {
            continue;
        }

        for (int64_t kx = 0; kx < kernel_width; ++kx) {
            const int64_t x_num =
                ox + padding_w - kx * dilation_w;

            if (x_num < 0 || x_num % stride_w != 0) {
                continue;
            }

            const int64_t ix = x_num / stride_w;
            if (ix < 0 || ix >= in_width) {
                continue;
            }

            for (int64_t ic_local = 0;
                 ic_local < in_channels_per_group;
                 ++ic_local) {
                const int64_t ic =
                    group * in_channels_per_group + ic_local;

                const int64_t x_idx =
                    ((batch * in_channels + ic) * in_height + iy) *
                        in_width +
                    ix;

                const int64_t weight_idx =
                    (((ic * out_channels_per_group + oc_in_group) *
                          kernel_height +
                      ky) *
                         kernel_width +
                     kx);

                acc += x[x_idx] * weight[weight_idx];
            }
        }
    }

    const int64_t output_idx =
        ((batch * out_channels + oc) * out_height + oy) * out_width + ox;

    output[output_idx] = acc;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "Weight must be contiguous");
    TORCH_CHECK(
        bias.numel() == 0 || bias.is_cuda(),
        "Bias must be CUDA or empty");
    TORCH_CHECK(
        bias.numel() == 0 || bias.is_contiguous(),
        "Bias must be contiguous");

    TORCH_CHECK(x.dim() == 4, "Input must have shape [N, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "Weight must have shape [C, O/G, KH, KW]");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int64_t batch = x.size(0);
    const int64_t in_channels = x.size(1);
    const int64_t in_height = x.size(2);
    const int64_t in_width = x.size(3);

    const int64_t kernel_height = weight.size(2);
    const int64_t kernel_width = weight.size(3);
    const int64_t out_channels_per_group = weight.size(1);
    const int64_t out_channels = out_channels_per_group * groups;

    TORCH_CHECK(in_channels % groups == 0, "Invalid input channel grouping");
    TORCH_CHECK(
        weight.size(0) == in_channels,
        "Weight input-channel dimension mismatch");

    const int64_t out_height =
        (in_height - 1) * stride_h -
        2 * padding_h +
        dilation_h * (kernel_height - 1) +
        1;

    const int64_t out_width =
        (in_width - 1) * stride_w -
        2 * padding_w +
        dilation_w * (kernel_width - 1) +
        1;

    TORCH_CHECK(out_height >= 0 && out_width >= 0, "Invalid output size");

    c10::cuda::CUDAGuard device_guard(x.device());

    auto output = torch::empty(
        {batch, out_channels, out_height, out_width},
        x.options());

    const int64_t total =
        batch * out_channels * out_height * out_width;

    constexpr int threads = 256;
    const int blocks =
        static_cast<int>((total + threads - 1) / threads);

    const bool has_bias = bias.numel() != 0;

    AT_DISPATCH_FLOATING_TYPES(
        x.scalar_type(),
        "conv_transpose2d_cuda",
        [&] {
            const scalar_t* bias_ptr =
                has_bias ? bias.data_ptr<scalar_t>() : nullptr;

            transposed_conv2d_kernel<scalar_t>
                <<<blocks, threads, 0, at::cuda::getDefaultCUDAStream()>>>(
                    x.data_ptr<scalar_t>(),
                    weight.data_ptr<scalar_t>(),
                    bias_ptr,
                    output.data_ptr<scalar_t>(),
                    batch,
                    in_channels,
                    in_height,
                    in_width,
                    out_channels,
                    out_height,
                    out_width,
                    kernel_height,
                    kernel_width,
                    stride_h,
                    stride_w,
                    padding_h,
                    padding_w,
                    dilation_h,
                    dilation_w,
                    groups,
                    has_bias ? 1 : 0);
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

    _transpose_conv_ext = load_inline(
        name="custom_grouped_transpose_conv2d",
        cpp_sources=cpp_source,
        cuda_sources=cuda_source,
        functions=None,
        extra_cflags=["-O3"],
        extra_cuda_cflags=["-O3"],
        with_cuda=True,
        verbose=False,
    )
    return _transpose_conv_ext


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        _get_transpose_conv_ext()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA input")

        x = x.contiguous()
        weight = self.conv_transpose2d.weight.contiguous()

        if self.conv_transpose2d.bias is None:
            bias = x.new_empty((0,))
        else:
            bias = self.conv_transpose2d.bias.contiguous()

        return _transpose_conv_ext.forward(
            x,
            weight,
            bias,
            int(self.stride[0]),
            int(self.stride[1]),
            int(self.padding[0]),
            int(self.padding[1]),
            int(self.dilation[0]),
            int(self.dilation[1]),
            int(self.groups),
        )

